package com.forgeci.api;
import com.forgeci.application.organization.OrganizationService; import jakarta.validation.Valid; import jakarta.validation.constraints.*; import java.util.*; import org.springframework.http.*; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/organizations") public class OrganizationController { private final OrganizationService service; public OrganizationController(OrganizationService s){service=s;} @PostMapping ResponseEntity<Response> create(Authentication a,@Valid @RequestBody Request r){var o=service.create(UUID.fromString(a.getName()),r.name(),r.slug());return ResponseEntity.status(HttpStatus.CREATED).body(Response.from(o));} record Request(@NotBlank @Size(max=120) String name,@NotBlank @Size(max=80) String slug){} record Response(UUID id,String name,String slug){static Response from(com.forgeci.domain.organization.Organization o){return new Response(o.getId(),o.getName(),o.getSlug());}} }
